const $=s=>document.querySelector(s), keys=new Set();let demo=true,armed=false,ws=null,ready=false,lastFrame=0,objectURL=null,frames=0,lastFps=performance.now();
const controls=[...document.querySelectorAll('[data-key]')];
function send(o){if(ws?.readyState===1&&ws.bufferedAmount<4096)ws.send(JSON.stringify(o))}
function disarm(){armed=false;keys.clear();send({type:'stop'});$('#arm').textContent='Activer les commandes';controls.forEach(b=>b.classList.remove('pressed'));$('#power').textContent='0';$('#steer').textContent='0°';$('#movement').textContent='À L’ARRÊT'}
function fail(msg){disarm();ready=false;$('#status').textContent='● DÉCONNECTÉ';$('#linknote').textContent=msg;$('#connecterror').textContent=msg}
function command(){const t=(keys.has('ArrowUp')?1:0)-(keys.has('ArrowDown')?1:0),s=(keys.has('ArrowRight')?1:0)-(keys.has('ArrowLeft')?1:0);return {type:'drive',throttle:armed?t*Number($('#limit').value):0,steer:armed?s*25:0,pan:Number($('#pan').value),tilt:Number($('#tilt').value)}}
setInterval(()=>{if(!demo&&armed&&Date.now()-lastFrame>800){disarm();$('#linknote').textContent='Vidéo interrompue : commandes désactivées.'}const c=command();if(ready)send(c);$('#power').textContent=Math.abs(c.throttle);$('#steer').textContent=c.steer+'°';$('#movement').textContent=c.throttle>0?'EN AVANT':c.throttle<0?'MARCHE ARRIÈRE':'À L’ARRÊT';controls.forEach(b=>b.classList.toggle('pressed',keys.has(b.dataset.key)&&armed))},80);
$('#arm').onclick=()=>{if(armed){disarm();return}if(!demo&&(!ready||Date.now()-lastFrame>800)){$('#linknote').textContent='Attends la connexion et une image vidéo récente.';return}keys.clear();armed=true;send({type:'arm'});$('#arm').textContent='Commandes actives · désactiver'};
$('#stop').onclick=disarm;$('#neutral').onclick=()=>keys.clear();$('#limit').oninput=()=>$('#limitValue').textContent=$('#limit').value+' %';$('#recenter').onclick=()=>{$('#pan').value=0;$('#tilt').value=0};
controls.forEach(b=>{b.onpointerdown=e=>{e.preventDefault();if(armed){b.setPointerCapture(e.pointerId);keys.add(b.dataset.key)}};b.onpointerup=b.onpointercancel=b.onlostpointercapture=()=>keys.delete(b.dataset.key)});
const keymap={z:'ArrowUp',w:'ArrowUp',s:'ArrowDown',q:'ArrowLeft',a:'ArrowLeft',d:'ArrowRight'};
addEventListener('keydown',e=>{if(e.code==='Space'&&!/INPUT|TEXTAREA/.test(e.target.tagName)){e.preventDefault();disarm();return}if($('#dialog').open||/INPUT|TEXTAREA/.test(e.target.tagName))return;const k=keymap[e.key.toLowerCase()]||e.key;if(k.startsWith('Arrow')){e.preventDefault();if(armed)keys.add(k)}});addEventListener('keyup',e=>keys.delete(keymap[e.key.toLowerCase()]||e.key));addEventListener('blur',disarm);document.addEventListener('visibilitychange',()=>{if(document.hidden)disarm()});addEventListener('pagehide',()=>{disarm();ws?.close()});
$('#settings').onclick=()=>{disarm();$('#dialog').showModal()};$('#close').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('cancel',disarm);
$('#demo').onclick=()=>{disarm();ready=false;demo=true;ws?.close();ws=null;$('#video').hidden=true;$('#scene').hidden=false;$('#status').textContent='● SIMULATION';$('#feed').textContent='ENVIRONNEMENT SIMULÉ';$('#fps').textContent='VUE D’ESSAI · AUCUNE VOITURE CONNECTÉE';$('#linknote').textContent='Mode démonstration : le circuit et le déplacement sont simulés.';$('#dialog').close()};
$('#connectform').onsubmit=e=>{e.preventDefault();disarm();ready=false;ws?.close();let u;try{u=new URL($('#url').value);if(!['ws:','wss:'].includes(u.protocol)||u.username||u.password)throw Error('Utilise une adresse ws:// ou wss:// sans identifiants.');if(location.protocol==='https:'&&u.protocol!=='wss:')throw Error('Depuis le site hébergé, une adresse wss:// est nécessaire.')}catch(err){$('#connecterror').textContent=err.message;return}demo=false;const socket=new WebSocket(u.href);ws=socket;socket.binaryType='blob';$('#connecterror').textContent='Connexion…';$('#status').textContent='● CONNEXION';let timeout=setTimeout(()=>{if(!ready&&ws===socket){fail('Connexion expirée. Vérifie le serveur, le réseau et le certificat TLS.');socket.close()}},8000);socket.onopen=()=>socket.send(JSON.stringify({type:'auth',token:$('#token').value}));socket.onmessage=e=>{if(ws!==socket)return;if(e.data instanceof Blob){if(!ready)return;lastFrame=Date.now();const next=URL.createObjectURL(e.data);if(objectURL)URL.revokeObjectURL(objectURL);objectURL=next;$('#video').src=next;$('#video').hidden=false;$('#scene').hidden=true;frames++;if(performance.now()-lastFps>1000){$('#fps').textContent=frames+' IMAGES/S · FLUX JPEG';frames=0;lastFps=performance.now()}return}try{const m=JSON.parse(e.data);if(m.type==='ready'){clearTimeout(timeout);ready=true;$('#token').value='';$('#dialog').close();$('#status').textContent='● CONNECTÉ';$('#feed').textContent='CAMÉRA EMBARQUÉE · DIRECT';$('#linknote').textContent='Liaison établie. Attends la vidéo puis active les commandes.'}else if(m.type==='fault'){disarm();$('#linknote').textContent=m.message}else if(m.type==='error'){fail(m.message);socket.close()}}catch{fail('Réponse du serveur invalide.');socket.close()}};socket.onerror=()=>{if(ws===socket&&!demo)fail('Échec réseau. Vérifie l’adresse et le certificat TLS.')};socket.onclose=()=>{clearTimeout(timeout);if(ws===socket&&!demo){fail('Liaison fermée : rover désactivé.');$('#video').hidden=true;$('#scene').hidden=false}}};
$('#fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else $('#view').requestFullscreen?.().catch(()=>{$('#linknote').textContent='Plein écran indisponible sur ce navigateur.'})};
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{disarm();document.querySelectorAll('[data-tab]').forEach(n=>n.classList.toggle('selected',n===b));$('#drive').hidden=b.dataset.tab!=='drive';$('#atelier').hidden=b.dataset.tab!=='atelier'});
if(location.hash==='#materiel')document.querySelector('[data-tab=atelier]').click();
// Circuit d’essai : aucune donnée matérielle n’est simulée comme réelle.
const canvas=$('#scene'),ctx=canvas.getContext('2d');let car={x:0,y:0,a:-Math.PI/2},last=performance.now();
function draw(now){const dt=Math.min((now-last)/1000,.05);last=now;const r=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio,2);if(canvas.width!==Math.round(r.width*dpr)||canvas.height!==Math.round(r.height*dpr)){canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);const w=r.width,h=r.height;ctx.fillStyle='#172521';ctx.fillRect(0,0,w,h);ctx.save();ctx.translate(w/2,h/2);const c=command();if(demo&&armed){car.a+=c.steer/25*c.throttle/25*dt*1.6;car.x+=Math.cos(car.a)*c.throttle*dt*2;car.y+=Math.sin(car.a)*c.throttle*dt*2;car.x=Math.max(-w*.39,Math.min(w*.39,car.x));car.y=Math.max(-h*.35,Math.min(h*.35,car.y))}ctx.strokeStyle='#293b33';ctx.lineWidth=1;for(let x=-w;x<w;x+=36){ctx.beginPath();ctx.moveTo(x,-h);ctx.lineTo(x,h);ctx.stroke()}for(let y=-h;y<h;y+=36){ctx.beginPath();ctx.moveTo(-w,y);ctx.lineTo(w,y);ctx.stroke()}ctx.strokeStyle='#526351';ctx.lineWidth=52;ctx.beginPath();ctx.roundRect(-w*.35,-h*.28,w*.7,h*.56,65);ctx.stroke();ctx.strokeStyle='#d5deae55';ctx.lineWidth=1;ctx.setLineDash([8,14]);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#263f31';for(let i=0;i<6;i++){const x=Math.cos(i)*w*.17,y=Math.sin(i)*h*.09;ctx.beginPath();ctx.arc(x,y,14+i*2,0,Math.PI*2);ctx.fill()}ctx.save();ctx.translate(car.x,car.y);ctx.rotate(car.a+Math.PI/2);ctx.shadowColor='#c6f381';ctx.shadowBlur=20;ctx.fillStyle='#c6f381';ctx.beginPath();ctx.roundRect(-13,-21,26,42,7);ctx.fill();ctx.shadowBlur=0;ctx.fillStyle='#14261c';ctx.fillRect(-8,-12,16,12);ctx.fillStyle='#0a100d';for(const x of [-18,13])for(const y of [-15,8])ctx.fillRect(x,y,5,12);ctx.fillStyle='#f0ffd0';ctx.fillRect(-9,-22,5,3);ctx.fillRect(4,-22,5,3);ctx.restore();ctx.restore();requestAnimationFrame(draw)}requestAnimationFrame(draw);
if(location.protocol==='http:')$('#url').value='ws://'+location.host+'/ws';
